      "vulnerable_snippet": "const query = `SELECT * FROM users WHERE id = '${userId}'`;",
      "attack_vector": "Explain how an adversary exploits this vulnerability",
      "impact": "Full database exfiltration, modification, or lateral privilege escalation",
      "remediation": "Replace dynamic concatenation with parameterized queries or prepared statements"
